    31→    scene.physics.add.existing(this);
    32→
    33→    // 캐릭터 크기 설정
    34→    this.setDisplaySize(50, 80);
    35→
    36→    // 히트박스: 텍스처 해상도와 무관하게 world pixel 크기 고정
    37→    // setSize/setOffset 은 frame pixel 단위이므로 scaleX/Y 로 역산
    38→    // 목표 world 크기: 20×40 px (display 50×80 의 40%/50%), 중앙 정렬
    39→    const sx = this.scaleX;  // = 50 / textureWidth
    40→    const sy = this.scaleY;  // = 80 / textureHeight
    41→    this.setSize(20 / sx, 40 / sy);
    42→    this.setOffset((50 - 20) / 2 / sx, (80 - 40) / 2 / sy);
    43→
    44→    // 물리 설정
    45→    this.setCollideWorldBounds(true);
    46→    this.setImmovable(true);
    47→
    48→    // Phaser 키보드 입력
    49→    this.cursors = scene.input.keyboard!.createCursorKeys();
    50→
    51→    // window 레벨 키보드 이벤트 (canvas 포커스와 무관하게 동작)
    52→    this.onKeyDown = (e: KeyboardEvent) => {
    53→      if (e.key === 'ArrowLeft') this.leftKeyDown = true;
    54→      if (e.key === 'ArrowRight') this.rightKeyDown = true;
    55→    };
    56→    this.onKeyUp = (e: KeyboardEvent) => {
    57→      if (e.key === 'ArrowLeft') this.leftKeyDown = false;
    58→      if (e.key === 'ArrowRight') this.rightKeyDown = false;
    59→    };
    60→    // capture: true → window capture phase는 이벤트 전파 최우선 단계
    61→    // Vercel Preview 툴바 등 외부 스크립트가 ArrowLeft/Right를 가로채도 우선 실행됨
    62→    window.addEventListener('keydown', this.onKeyDown, { capture: true });
    63→    window.addEventListener('keyup', this.onKeyUp, { capture: true });
    64→
    65→    // 씬 종료 시 이벤트 리스너 정리
    66→    scene.events.once('shutdown', this.removeKeyListeners, this);
    67→    scene.events.once('destroy', this.removeKeyListeners, this);
    68→  }
    69→
    70→  private removeKeyListeners() {
    71→    window.removeEventListener('keydown', this.onKeyDown, { capture: true });
    72→    window.removeEventListener('keyup', this.onKeyUp, { capture: true });
    73→  }
    74→
    75→  update() {
    76→    let isMoving = false;
    77→
    78→    // 좌우 이동 (Phaser 키보드 OR window 레벨 키보드 둘 다 체크)
    79→    if (this.cursors.left.isDown || this.leftKeyDown) {
    80→      this.setVelocityX(-this.speed);
    81→      this.setTexture(`${this.texturePrefix}left`);
    82→      isMoving = true;
    83→    } else if (this.cursors.right.isDown || this.rightKeyDown) {
    84→      this.setVelocityX(this.speed);
    85→      this.setTexture(`${this.texturePrefix}right`);
    86→      isMoving = true;
    87→    } else {
    88→      this.setVelocityX(0);
    89→    }
    90→
    91→    // 터치/마우스 입력 처리 (화면 중앙 기준)
    92→    if (this.scene.input.activePointer.isDown) {
    93→      const pointerX = this.scene.input.activePointer.x;
    94→      const screenCenter = this.scene.cameras.main.width / 2;
    95→
    96→      if (pointerX < screenCenter) {
    97→        this.setVelocityX(-this.speed);
    98→        this.setTexture(`${this.texturePrefix}left`); // 왼쪽 이미지
    99→        isMoving = true;
   100→      } else if (pointerX > screenCenter) {
   101→        this.setVelocityX(this.speed);
   102→        this.setTexture(`${this.texturePrefix}right`); // 오른쪽 이미지
   103→        isMoving = true;
   104→      }
   105→    }
   106→
   107→    // 멈춰있을 때는 정면 이미지
   108→    if (!isMoving && this.body?.velocity.x === 0) {
   109→      this.setTexture(`${this.texturePrefix}front`);
   110→    }
   111→  }
   112→
   113→  // 헤르메스 신발 효과: 10초간 속도 2배 증가
   114→  activateSpeedBoost(duration: number = 10000) {
   115→    // 기존 타이머가 있으면 제거
   116→    if (this.speedBoostTimer) {
   117→      this.speedBoostTimer.remove();
   118→    }
   119→
   120→    // 속도 증가 (2배)
   121→    this.speedBoostActive = true;
   122→    this.speed = this.baseSpeed * 2;
   123→
   124→    // 시각적 피드백: 노란색 틴트
   125→    this.setTint(0xffff00);
   126→
   127→    // 일정 시간 후 원래 속도로 복구
   128→    this.speedBoostTimer = this.scene.time.addEvent({
   129→      delay: duration,
   130→      callback: () => {
   131→        this.speedBoostActive = false;
   132→        this.speed = this.baseSpeed;
   133→        // 무적이 아니면 틴트 제거
   134→        if (!this.isInvincible) {
   135→          this.clearTint();
   136→        } else {
   137→          // 무적 효과만 남김
   138→          this.setTint(0x00ffff);
   139→        }
   140→      },
   141→      callbackScope: this
   142→    });
   143→  }
   144→
   145→  // 무지개 별 효과: 5초간 무적
   146→  activateInvincibility(duration: number = 5000) {
   147→    // 기존 타이머가 있으면 제거
   148→    if (this.invincibleTimer) {
   149→      this.invincibleTimer.remove();
   150→    }
   151→    if (this.rainbowTimer) {
   152→      this.rainbowTimer.remove();
   153→    }
   154→
   155→    // 무적 활성화
   156→    this.isInvincible = true;
   157→
   158→    // 무지개 색상 배열 (빨주노초파남보)
   159→    const rainbowColors = [
   160→      0xff0000, // 빨강
   161→      0xff7700, // 주황
   162→      0xffff00, // 노랑
   163→      0x00ff00, // 초록
   164→      0x00ffff, // 하늘
   165→      0x0000ff, // 파랑
   166→      0xff00ff  // 보라
   167→    ];
   168→
   169→    let colorIndex = 0;
   170→
   171→    // 무지개 색상 순환 효과 (150ms마다 색상 변경)
   172→    this.rainbowTimer = this.scene.time.addEvent({
   173→      delay: 150,
   174→      callback: () => {
   175→        this.setTint(rainbowColors[colorIndex]);
   176→        colorIndex = (colorIndex + 1) % rainbowColors.length;
   177→      },
   178→      callbackScope: this,
   179→      loop: true
   180→    });
   181→
   182→    // 일정 시간 후 무적 해제
   183→    this.invincibleTimer = this.scene.time.addEvent({
   184→      delay: duration,
   185→      callback: () => {
   186→        this.isInvincible = false;
   187→        // 무지개 타이머 정지
   188→        if (this.rainbowTimer) {
   189→          this.rainbowTimer.remove();
   190→          this.rainbowTimer = undefined;
   191→        }
   192→        // 속도 증가가 아니면 틴트 제거
   193→        if (!this.speedBoostActive) {
   194→          this.clearTint();
   195→        } else {
   196→          // 속도 증가 효과만 남김
   197→          this.setTint(0xffff00);
   198→        }
   199→      },
   200→      callbackScope: this
   201→    });
   202→  }
   203→
   204→  // 무적 상태 확인
   205→  getIsInvincible(): boolean {
   206→    return this.isInvincible;
   207→  }
   208→
   209→  // 효과 정리 (씬 종료 시)
